tool_input.command:
cd /app && python3 << 'EOF'
import mujoco
import xml.etree.ElementTree as ET

# Parse the XML to see all tunable elements
tree = ET.parse('model_ref.xml')
root = tree.getroot()

print("XML structure:")
for elem in root.iter():
    if elem.tag in ['option', 'compiler', 'size']:
        print(f"  {elem.tag}: {elem.attrib}")
    if elem.tag == 'joint':
        print(f"  {elem.tag}: {elem.attrib}")
    if elem.tag == 'plugin' and 'config' in str(ET.tostring(elem)):
        print(f"  {elem.tag}: {elem.attrib}")
        for child in elem:
            if child.tag == 'config':
                print(f"    config: {child.attrib}")

EOF

